/* Availability and offers reuse the Trade Center's valuation and legality rules. */
let tradesTab='center',tradeBlockBusy=false;
const TRADE_BLOCK_SKILLS={all:'Any skill',tp:'3-point shooting',pss:'Playmaking',per:'Perimeter defense',rim:'Rim defense',reb:'Rebounding',lay:'Finishing'};
let tradeBlockFilters={asset:'all',position:'all',skill:'all',prospects:false,sort:'overall'};
function tradeBlockStore(){return state.tradeBlock??={players:[],picks:[],offers:[],nextId:1,revision:0,lastRun:''}}
function tradeBlockListings(){const b=tradeBlockStore();return {players:team().roster.filter(p=>b.players.includes(p.id)),picks:tradePicks(team()).filter(p=>b.picks.includes(tradePickKey(p)))}}
function openTradeBlock(){tradesTab='block';go('Trades')}
function switchTradesTab(tab){tradesTab=tab==='block'?'block':'center';render()}
async function tradeBlockToggle(kind,key){if(tradeBlockBusy||tradeCenterBusy||!ownerCanManage())return;const valid=kind==='players'?team().roster.some(p=>p.id===key):kind==='picks'&&tradePicks(team()).some(p=>tradePickKey(p)===key);if(!valid)return toast('This asset is no longer available.');const before=snapshotState(),b=tradeBlockStore(),live=tradeBlockListings();b.players=live.players.map(p=>p.id);b.picks=live.picks.map(tradePickKey);if(!b[kind].includes(key)&&b.players.length+b.picks.length>=30)return toast('List up to 30 assets at a time.');tradeBlockBusy=true;try{b[kind]=b[kind].includes(key)?b[kind].filter(x=>x!==key):[...b[kind],key];b.revision++;b.lastRun='';if(await save()===false){state=before;toast('Could not save your trade block. Please try again.')}}catch(e){state=before;toast('Could not save your trade block. Please try again.')}finally{tradeBlockBusy=false;render()}}
function tradeBlockPlayerReason(p,t){if(tradeRestrictionText(p))return '';if(p.tradeDemand&&(!p.dissatisfaction||p.dissatisfaction.active?.visibility==='public'))return 'Publicly requested a trade';if(p.ovr>=88)return '';const rank=[...t.roster].sort((a,b)=>b.ovr-a.ovr).findIndex(q=>q.id===p.id);if(tradeTimeline(t)==='Rebuilding'&&p.age>=29)return 'Veteran available for future assets';if(rank>=5&&t.roster.some(q=>q.id!==p.id&&q.pos===p.pos&&q.ovr>=p.ovr))return 'Positional surplus';if(tradeYears(p)===1&&rank>=5)return 'Expiring contract';if(rank>=8)return 'Outside the core rotation';return ''}
function tradeBlockLeagueAssets(){const rows=[];for(const t of state.teams.filter(t=>t.id!==controlledTeamId()).filter(t=>!expansionPendingSeason(t))){const players=t.roster.map(p=>({p,t,reason:tradeBlockPlayerReason(p,t)})).filter(r=>r.reason).sort((a,b)=>b.p.ovr-a.p.ovr).slice(0,5);rows.push(...players);const available=tradePicks(t).sort((a,b)=>tradePickValue(a,t)-tradePickValue(b,t)),limit=tradeTimeline(t)==='Contender'?2:1,picks=[...available.filter(p=>p.round===1).slice(0,limit),...available.filter(p=>p.round!==1).slice(0,limit)];for(const pick of picks)rows.push({pick,t,reason:tradeTimeline(t)==='Contender'?'Seeking immediate help':'Available in a balanced package'});}return rows}
function tradeBlockFilteredAssets(){const f=tradeBlockFilters;return tradeBlockLeagueAssets().filter(r=>f.asset==='all'||(f.asset==='players'?!!r.p:!!r.pick)).filter(r=>r.p?(f.position==='all'||r.p.pos===f.position)&&(f.skill==='all'||r.p.attributes?.[f.skill]>=75)&&(!f.prospects||r.p.age<=24&&r.p.pot>r.p.ovr):f.position==='all'&&f.skill==='all'&&!f.prospects).sort((a,b)=>{if(!a.p||!b.p)return a.p?-1:b.p?1:a.pick.year-b.pick.year||a.pick.round-b.pick.round;return (f.sort==='potential'?b.p.pot-a.p.pot:f.sort==='salary'?a.p.salary-b.p.salary:f.sort==='age'?a.p.age-b.p.age:b.p.ovr-a.p.ovr)||a.p.id-b.p.id})}
function tradeBlockFilter(key,value){if(key==='asset'&&['all','players','picks'].includes(value)||key==='position'&&['all','PG','SG','SF','PF','C'].includes(value)||key==='skill'&&Object.hasOwn(TRADE_BLOCK_SKILLS,value)||key==='sort'&&['overall','potential','salary','age'].includes(value)||key==='prospects'&&typeof value==='boolean')tradeBlockFilters[key]=value;render()}
function tradeBlockOfferSignature(o){return JSON.stringify([o.club,[...o.out].sort((a,b)=>a-b),[...o.into].sort((a,b)=>a-b),[...o.outPicks].sort(),[...o.inPicks].sort()])}
function tradeBlockAssessment(o,requireListing=true){const club=state.teams[o.club],errors=[];if(!club||club.id===controlledTeamId())return {errors:['Trade partner unavailable.']};const out=team().roster.filter(p=>o.out.includes(p.id)),into=club.roster.filter(p=>o.into.includes(p.id)),outPicks=tradePicks(team()).filter(p=>o.outPicks.includes(tradePickKey(p))),inPicks=tradePicks(club).filter(p=>o.inPicks.includes(tradePickKey(p)));
 if(out.length!==o.out.length||into.length!==o.into.length||outPicks.length!==o.outPicks.length||inPicks.length!==o.inPicks.length)errors.push('An asset is no longer available.');
 if(requireListing){const b=tradeBlockStore();if(o.out.some(id=>!b.players.includes(id))||o.outPicks.some(k=>!b.picks.includes(k)))errors.push('An outgoing asset was removed from your block.');}
 if(!out.length&&!outPicks.length||!into.length&&!inPicks.length)errors.push('Each team must send an asset.');
 errors.push(...tradeLegality(team(),club,out,into,0,outPicks,inPicks));if(errors.length)return {errors,out,into,outPicks,inPicks,club};
 const ai=tradeSideAssessment(club,into,out,inPicks,outPicks),user=tradeSideAssessment(team(),out,into,outPicks,inPicks);
 // Hard league rules are checked before valuing any proposed package.
 if(!ai.accepted)errors.push(...ai.reasons);if(user.received<user.sent*.85)errors.push('Return falls below the trade-block valuation range.');
 if(!errors.length&&!wnbaEnabled()){const delta=out.reduce((s,p)=>s+p.salary,0)-into.reduce((s,p)=>s+p.salary,0);if(ownerPayroll(team())+financeDead(team())-delta>financeRosterLimit(team())+.00001||ownerPayroll(club)+financeDead(club)+delta>financeRosterLimit(club)+.00001)errors.push('Payroll including waived guarantees exceeds the spending limit.');}
 return {errors,out,into,outPicks,inPicks,ai,user,club};
}
function tradeBlockOfferStatus(o){if(o.status!=='open')return o.status==='accepted'?'Accepted':'Declined';if(o.year!==state.year||state.day>o.day+7)return 'Expired';const assessment=tradeBlockAssessment(o);return assessment.errors[0]||'Open'}
function generateTradeBlockOffers(){if(!ownerCanManage()||tradeDeadlinePassed())return 0;const b=tradeBlockStore(),listed=tradeBlockListings(),stamp=state.year+':'+state.day+':'+b.revision;if(b.lastRun===stamp||!listed.players.length&&!listed.picks.length)return 0;b.lastRun=stamp;
 const known=new Set(b.offers.filter(o=>o.year===state.year&&state.day<=o.day+7).map(tradeBlockOfferSignature)),league=tradeBlockLeagueAssets();let added=0;
 for(const club of state.teams.filter(t=>t.id!==controlledTeamId()).filter(t=>!expansionPendingSeason(t))){let best=null,bestScore=-Infinity;const theirPlayers=league.filter(r=>r.t.id===club.id&&r.p).map(r=>r.p),theirPicks=league.filter(r=>r.t.id===club.id&&r.pick).map(r=>r.pick),ourPicks=listed.picks.slice(0,6),ourPlayers=listed.players.filter(p=>!tradeRestrictionText(p));
 const consider=(out,into,outPicks=[],inPicks=[])=>{const offer={club:club.id,out:out.map(p=>p.id),into:into.map(p=>p.id),outPicks:outPicks.map(tradePickKey),inPicks:inPicks.map(tradePickKey)};if(known.has(tradeBlockOfferSignature(offer)))return;const m=tradeBlockAssessment(offer);if(m.errors.length)return;const score=m.user.received/Math.max(.1,m.user.sent);if(score>bestScore){best=offer;bestScore=score}};
 for(const p of ourPlayers){for(const q of theirPlayers){consider([p],[q]);for(const pick of ourPicks.slice(0,2))consider([p],[q],[pick]);for(const pick of theirPicks.slice(0,2))consider([p],[q],[],[pick]);}for(const pick of theirPicks)consider([p],[],[],[pick]);}
 for(const pick of ourPicks){for(const q of theirPlayers)consider([],[q],[pick]);for(const theirs of theirPicks)consider([],[],[pick],[theirs]);}
 if(best){const sig=tradeBlockOfferSignature(best);known.add(sig);b.offers.unshift({...best,id:b.nextId++,year:state.year,day:state.day,status:'open'});added++;}if(added>=6)break;
 }
 b.offers=b.offers.slice(0,40);if(added)addGMMessage('Trade block','Front office',added+' trade-block offer'+(added===1?'':'s')+' received','Teams have responded to the assets on your trade block. Review their packages in Trades → Trade Block. Offers last seven league days and are rechecked before a trade can be completed.');return added;
}
async function requestTradeBlockOffers(){if(tradeBlockBusy||tradeCenterBusy||!ownerCanManage())return;if(tradeDeadlinePassed())return toast('Trading reopens after the championship.');const before=snapshotState();tradeBlockBusy=true;try{const count=generateTradeBlockOffers();if(await save()===false){state=before;toast('Could not save trade-block offers. Please try again.')}else toast(count?count+' new offer'+(count===1?'':'s')+' received.':'No new legal offers today. Adjust your listings or advance the season.');}catch(e){state=before;toast('Could not generate offers. Please try again.')}finally{tradeBlockBusy=false;render()}}
function reviewTradeBlockOffer(id){const o=tradeBlockStore().offers.find(x=>x.id===id);if(!o||tradeBlockOfferStatus(o)!=='Open')return toast('This offer is no longer available.');tradesTab='center';addTradeOffer({club:o.club,outgoingPlayerIds:o.out,incomingPlayerIds:o.into,outgoingPickKeys:o.outPicks,incomingPickKeys:o.inPicks,reasoning:'Responding to a trade-block offer from '+state.teams[o.club].city});}
async function declineTradeBlockOffer(id){if(tradeBlockBusy||tradeCenterBusy||!ownerCanManage())return;const o=tradeBlockStore().offers.find(o=>o.id===id);if(!o||o.status!=='open')return;const before=snapshotState();tradeBlockBusy=true;try{o.status='declined';if(await save()===false){state=before;toast('Could not save your response.')}}catch(e){state=before;toast('Could not save your response.')}finally{tradeBlockBusy=false;render()}}
function tradeBlockTarget(club,id,pick=false){const row=tradeBlockLeagueAssets().find(r=>r.t.id===club&&(pick?r.pick&&tradePickKey(r.pick)===id:r.p?.id===id));if(!row)return toast('This asset is no longer on the league block.');tradesTab='center';addTradeOffer({club,outgoingPlayerIds:[],incomingPlayerIds:pick?[]:[id],outgoingPickKeys:[],incomingPickKeys:pick?[id]:[],reasoning:'Enquiring about an asset on the league trade block.'});}
function tradeBlockRecordTrade(m){if(!state.tradeBlock)return;const b=state.tradeBlock,sig=tradeBlockOfferSignature({club:m.club.id,out:m.out.map(p=>p.id),into:m.incoming.map(p=>p.id),outPicks:m.outPicks.map(tradePickKey),inPicks:m.inPicks.map(tradePickKey)});for(const o of b.offers)if(o.status==='open'&&tradeBlockOfferSignature(o)===sig)o.status='accepted';b.players=b.players.filter(id=>team().roster.some(p=>p.id===id));const available=new Set(tradePicks(team()).map(tradePickKey));b.picks=b.picks.filter(key=>available.has(key));b.revision++;b.lastRun='';}
function tradeBlockPackage(o,side){const own=side==='out',ids=own?o.out:o.into,keys=own?o.outPicks:o.inPicks;return [...ids.map(id=>{const p=state.teams.flatMap(t=>t.roster).find(p=>p.id===id)||state.free.find(p=>p.id===id);return p?p.name+' ('+p.pos+', '+p.ovr+' OVR)':'Player no longer available'}),...keys.map(k=>{const [year,origin,round]=k.split(':').map(Number);return year+' R'+round+' ('+(state.teams[origin]?.abbr||'Former team')+')'})].map(escapeHTML).join(', ')}
function tradeBlockView(){const b=tradeBlockStore(),listed=tradeBlockListings(),rows=tradeBlockFilteredAssets(),f=tradeBlockFilters,offers=b.offers.map(o=>({o,status:tradeBlockOfferStatus(o)}));return `<div class="trade-block"><section class="panel note"><div class="panelhead"><div><h2>Your trade block</h2><p>${listed.players.length} players · ${listed.picks.length} picks listed</p></div><button class="primary" onclick="requestTradeBlockOffers()" ${tradeBlockBusy||tradeCenterBusy||tradeDeadlinePassed()||!ownerCanManage()?'disabled':''}>Find offers</button></div><p>List assets to invite proposals. Teams respond when you search and every seven league days. Listing a player does not trade them.</p>${tradeDeadlinePassed()?'<p>Trade deadline passed. Listings remain saved; offers resume after the championship.</p>':''}<div class="tb-columns"><details open><summary>Players</summary><div class="tb-list">${team().roster.map(p=>`<label class="tb-listing"><input type="checkbox" ${b.players.includes(p.id)?'checked':''} ${tradeBlockBusy||!ownerCanManage()?'disabled':''} onchange="tradeBlockToggle('players',${p.id})"><span>${escapeHTML(p.name)}<small>${p.pos} · ${p.ovr} OVR · ${p.pot} POT · ${money(p.salary)}${tradeRestrictionText(p)?' · '+tradeRestrictionText(p):''}</small></span></label>`).join('')}</div></details><details><summary>Draft picks</summary><div class="tb-list">${tradePicks(team()).map(p=>`<label class="tb-listing"><input type="checkbox" ${b.picks.includes(tradePickKey(p))?'checked':''} ${tradeBlockBusy||!ownerCanManage()?'disabled':''} onchange="tradeBlockToggle('picks','${tradePickKey(p)}')"><span>${escapeHTML(tradePickLabel(p))}</span></label>`).join('')||'<p>No tradeable picks.</p>'}</div></details></div></section>
 <section class="panel note"><h2>Incoming offers</h2><p>Offers expire after seven league days. Review a package in the Trade Center before accepting.</p>${offers.map(({o,status})=>`<article class="tb-offer"><h3>${escapeHTML(state.teams[o.club]?.city||'Former team')} · ${o.year}, day ${o.day+1}</h3><p><strong>You send:</strong> ${tradeBlockPackage(o,'out')}</p><p><strong>You receive:</strong> ${tradeBlockPackage(o,'into')}</p><div class="actions">${status==='Open'?`<button class="primary" onclick="reviewTradeBlockOffer(${o.id})">Review offer</button><button onclick="declineTradeBlockOffer(${o.id})" ${tradeBlockBusy?'disabled':''}>Decline</button>`:`<span class="muted">${escapeHTML(status)}</span>`}</div></article>`).join('')||'<p>No offers yet. List a player or draft pick, then select Find offers.</p>'}</section>
 <section class="panel"><div class="panelhead"><h2>League trade block</h2><span>${rows.length} available assets</span></div><div class="directory-filters"><label>Asset<select onchange="tradeBlockFilter('asset',this.value)">${[['all','Players and picks'],['players','Players'],['picks','Draft picks']].map(([k,v])=>`<option value="${k}" ${f.asset===k?'selected':''}>${v}</option>`).join('')}</select></label><label>Position<select onchange="tradeBlockFilter('position',this.value)">${['all','PG','SG','SF','PF','C'].map(k=>`<option value="${k}" ${f.position===k?'selected':''}>${k==='all'?'Any position':k}</option>`).join('')}</select></label><label>Skill (75+)<select onchange="tradeBlockFilter('skill',this.value)">${Object.entries(TRADE_BLOCK_SKILLS).map(([k,v])=>`<option value="${k}" ${f.skill===k?'selected':''}>${v}</option>`).join('')}</select></label><label>Sort<select onchange="tradeBlockFilter('sort',this.value)">${[['overall','Overall'],['potential','Potential'],['salary','Lowest salary'],['age','Youngest']].map(([k,v])=>`<option value="${k}" ${f.sort===k?'selected':''}>${v}</option>`).join('')}</select></label><label>Prospects<select onchange="tradeBlockFilter('prospects',this.value==='yes')"><option value="no">All players</option><option value="yes" ${f.prospects?'selected':''}>Age 24 or younger, with upside</option></select></label></div><p class="note">Availability reflects team direction, contract status and positional surplus. All proposed trades must pass roster, payroll and pick-ownership rules.</p><div class="tb-market">${rows.map(r=>`<article class="tb-offer"><h3>${escapeHTML(r.t.city+' '+r.t.name)}</h3>${r.p?`<button class="namebutton" onclick="profile(${r.p.id})">${escapeHTML(r.p.name)}</button><p>${r.p.pos} · Age ${r.p.age} · ${ratingMarkup(r.p.ovr)} OVR · ${ratingMarkup(r.p.pot)} POT · ${money(r.p.salary)} / year</p>`:`<strong>${escapeHTML(tradePickLabel(r.pick))}</strong>`}<p class="muted">${r.reason}</p><button onclick="tradeBlockTarget(${r.t.id},${r.p?r.p.id:"'"+tradePickKey(r.pick)+"'"},${!!r.pick})" ${tradeDeadlinePassed()||!ownerCanManage()?'disabled':''}>Build offer</button></article>`).join('')||'<p class="note">No assets match these filters.</p>'}</div></section></div>`}
const tradeCenterBeforeBlock=trades;trades=function(){return `<nav class="po-tabs" aria-label="Trade views"><button class="${tradesTab==='center'?'selected':''}" aria-pressed="${tradesTab==='center'}" onclick="switchTradesTab('center')">Trade Center</button><button class="${tradesTab==='block'?'selected':''}" aria-pressed="${tradesTab==='block'}" onclick="switchTradesTab('block')">Trade Block</button></nav>`+(tradesTab==='block'?tradeBlockView():tradeCenterBeforeBlock())};
const playerTradeBeforeBlock=playerTradeAction;playerTradeAction=function(...args){tradesTab='center';return playerTradeBeforeBlock(...args)};
const proposalBeforeBlock=reviewGMProposal;reviewGMProposal=function(...args){tradesTab='center';return proposalBeforeBlock(...args)};
const ownerDayBeforeBlock=ownerDay;ownerDay=function(...args){const result=ownerDayBeforeBlock(...args);if(state.tradeBlock&&state.day>0&&state.day%7===0)generateTradeBlockOffers();return result};
function readTradeBlock(raw,bad,count,year){if(raw===undefined)return undefined;const int=(n,l,h)=>Number.isInteger(n)&&n>=l&&n<=h,ids=(a,max)=>Array.isArray(a)&&a.length<=max&&new Set(a).size===a.length&&a.every(n=>int(n,0,10000000)),picks=(a,max)=>Array.isArray(a)&&a.length<=max&&new Set(a).size===a.length&&a.every(k=>{if(typeof k!=='string'||!/^\d{4,5}:\d{1,2}:[1-5]$/.test(k))return false;const [y,t,r]=k.split(':').map(Number);return int(y,1900,10009)&&int(t,0,count-1)});if(!raw||!ids(raw.players,30)||!picks(raw.picks,30)||raw.players.length+raw.picks.length>30||!int(raw.nextId,1,10000000)||!int(raw.revision,0,10000000)||typeof raw.lastRun!=='string'||raw.lastRun.length>80||!Array.isArray(raw.offers)||raw.offers.length>40)bad('invalid trade block');const seen=new Set();const offers=raw.offers.map(o=>{if(!o||!int(o.id,1,raw.nextId-1)||seen.has(o.id)||!int(o.club,1,count-1)||!int(o.year,1900,year)||!int(o.day,0,367)||!['open','accepted','declined'].includes(o.status)||!ids(o.out,5)||!ids(o.into,5)||!picks(o.outPicks,5)||!picks(o.inPicks,5)||!o.out.length&&!o.outPicks.length||!o.into.length&&!o.inPicks.length)bad('invalid trade-block offer');seen.add(o.id);return {id:o.id,club:o.club,year:o.year,day:o.day,status:o.status,out:[...o.out],into:[...o.into],outPicks:[...o.outPicks],inPicks:[...o.inPicks]}});return {players:[...raw.players],picks:[...raw.picks],offers,nextId:raw.nextId,revision:raw.revision,lastRun:raw.lastRun}}
